package com.nook.exception;
import com.nook.dto.ApiDtos.ErrorDto; import jakarta.servlet.http.HttpServletRequest; import org.slf4j.*; import org.springframework.http.*; import org.springframework.security.authentication.BadCredentialsException; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestControllerAdvice public class ApiExceptionHandler { private static final Logger log=LoggerFactory.getLogger(ApiExceptionHandler.class); @ExceptionHandler(ApiException.class) ResponseEntity<ErrorDto> api(ApiException e,HttpServletRequest r){return ResponseEntity.status(e.status).body(error(e.status,e.code,e.getMessage(),r,Map.of()));} @ExceptionHandler(BadCredentialsException.class) ResponseEntity<ErrorDto> auth(Exception e,HttpServletRequest r){return ResponseEntity.status(401).body(error(HttpStatus.UNAUTHORIZED,"INVALID_CREDENTIALS","Credenciales no válidas",r,Map.of()));} @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<ErrorDto> validation(MethodArgumentNotValidException e,HttpServletRequest r){Map<String,String> f=new LinkedHashMap<>();e.getBindingResult().getFieldErrors().forEach(x->f.put(x.getField(),x.getDefaultMessage()));return ResponseEntity.badRequest().body(error(HttpStatus.BAD_REQUEST,"VALIDATION_ERROR","Revisa los campos",r,f));} @ExceptionHandler(Exception.class) ResponseEntity<ErrorDto> other(Exception e,HttpServletRequest r){log.error("Unhandled API error method={} path={}",r.getMethod(),r.getRequestURI(),e);return ResponseEntity.status(500).body(error(HttpStatus.INTERNAL_SERVER_ERROR,"INTERNAL_ERROR","No hemos podido completar la operación",r,Map.of()));} private ErrorDto error(HttpStatus s,String c,String m,HttpServletRequest r,Map<String,String> f){return new ErrorDto(Instant.now(),s.value(),c,m,r.getRequestURI(),f);} }
